/**
 * A tokenizer for the small language described in the task.
 *
 * scan(input) returns { tokens } where tokens is an array of
 * { kind, text, value, line, col }. `text` is the raw source text of the
 * token; `value` is only set for string/rawstring and holds the decoded
 * string. On any lexical error a ScanError is thrown.
 */

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

function isDigit(c) {
  return c >= '0' && c <= '9'
}
function isHexDigit(c) {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}
function isBinDigit(c) {
  return c === '0' || c === '1'
}
function isOctDigit(c) {
  return c >= '0' && c <= '7'
}
function isLetter(c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}
function isIdentStart(c) {
  return isLetter(c) || c === '_'
}
function isIdentPart(c) {
  return isLetter(c) || isDigit(c) || c === '_'
}

class Scanner {
  constructor(input) {
    this.input = input
    this.len = input.length
    this.pos = 0
    this.line = 1
    this.col = 1
  }

  atEnd() {
    return this.pos >= this.len
  }

  // Current character as a single UTF-16 code unit view; sufficient since
  // all syntactically meaningful characters are ASCII.
  cur() {
    return this.pos < this.len ? this.input[this.pos] : ''
  }

  peekAt(offset) {
    const p = this.pos + offset
    return p < this.len ? this.input[p] : ''
  }

  here() {
    return { line: this.line, col: this.col }
  }

  error(pos, reason) {
    throw new ScanError(pos.line, pos.col, reason)
  }

  // Consumes exactly one code point (handling surrogate pairs) and updates
  // line/column bookkeeping per the spec's rules.
  advance() {
    const cp = this.input.codePointAt(this.pos)
    const width = cp > 0xffff ? 2 : 1
    this.pos += width
    if (cp === 0x0a) {
      this.line += 1
      this.col = 1
    } else if (cp === 0x09) {
      this.col = Math.floor((this.col - 1) / 4) * 4 + 5
    } else {
      this.col += 1
    }
    return cp
  }

  skipWhitespaceAndComments() {
    for (;;) {
      const c = this.cur()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }
      if (c === '/' && this.peekAt(1) === '/') {
        this.advance()
        this.advance()
        while (!this.atEnd() && this.cur() !== '\n') this.advance()
        continue
      }
      if (c === '/' && this.peekAt(1) === '*') {
        const start = this.here()
        this.advance()
        this.advance()
        let depth = 1
        while (depth > 0) {
          if (this.atEnd()) {
            this.error(start, 'unterminated block comment')
          }
          if (this.cur() === '/' && this.peekAt(1) === '*') {
            this.advance()
            this.advance()
            depth += 1
            continue
          }
          if (this.cur() === '*' && this.peekAt(1) === '/') {
            this.advance()
            this.advance()
            depth -= 1
            continue
          }
          this.advance()
        }
        continue
      }
      break
    }
  }

  // Consumes a run of digits (per isDigitFn) allowing single underscores
  // between two digits of the run. Returns the number of digit characters
  // actually consumed (excluding underscores).
  consumeDigitRun(isDigitFn) {
    let count = 0
    for (;;) {
      if (isDigitFn(this.cur())) {
        this.advance()
        count += 1
        continue
      }
      if (this.cur() === '_' && isDigitFn(this.peekAt(1))) {
        this.advance() // the underscore; loop will consume the following digit
        continue
      }
      break
    }
    return count
  }

  scanNumber() {
    const start = this.here()
    const startPos = this.pos
    let prefixBad = false

    const c0 = this.cur()
    const c1 = this.peekAt(1)
    if (c0 === '0' && (c1 === 'x' || c1 === 'X')) {
      this.advance()
      this.advance()
      const n = this.consumeDigitRun(isHexDigit)
      prefixBad = n === 0
    } else if (c0 === '0' && (c1 === 'b' || c1 === 'B')) {
      this.advance()
      this.advance()
      const n = this.consumeDigitRun(isBinDigit)
      prefixBad = n === 0
    } else if (c0 === '0' && (c1 === 'o' || c1 === 'O')) {
      this.advance()
      this.advance()
      const n = this.consumeDigitRun(isOctDigit)
      prefixBad = n === 0
    } else {
      this.consumeDigitRun(isDigit)
      if (this.cur() === '.' && isDigit(this.peekAt(1))) {
        this.advance()
        this.consumeDigitRun(isDigit)
      }
      if (this.cur() === 'e' || this.cur() === 'E') {
        const n1 = this.peekAt(1)
        const n2 = this.peekAt(2)
        if (isDigit(n1)) {
          this.advance()
          this.consumeDigitRun(isDigit)
        } else if ((n1 === '+' || n1 === '-') && isDigit(n2)) {
          this.advance()
          this.advance()
          this.consumeDigitRun(isDigit)
        }
      }
    }

    const core = this.input.slice(startPos, this.pos)
    const extraStart = this.pos
    while (!this.atEnd() && isIdentPart(this.cur())) this.advance()
    const extra = this.input.slice(extraStart, this.pos)

    if (prefixBad || extra.length > 0) {
      this.error(start, 'invalid number ' + core + extra)
    }
    return { kind: 'number', text: core, line: start.line, col: start.col }
  }

  scanIdent() {
    const start = this.here()
    const startPos = this.pos
    this.advance() // first char, already validated as ident start
    while (!this.atEnd() && isIdentPart(this.cur())) this.advance()
    const text = this.input.slice(startPos, this.pos)
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { kind, text, line: start.line, col: start.col }
  }

  scanString() {
    const start = this.here()
    this.advance() // opening quote
    let value = ''
    for (;;) {
      if (this.atEnd()) {
        this.error(start, 'unterminated string')
      }
      const charStart = this.here()
      const c = this.cur()
      if (c === '\n') {
        this.error(charStart, 'newline in string')
      }
      if (c === '"') {
        this.advance()
        break
      }
      if (c === '\\') {
        const backslashPos = this.here()
        this.advance() // backslash
        if (this.atEnd()) {
          this.error(start, 'unterminated string')
        }
        const ec = this.cur()
        if (ec === 'n') {
          value += '\n'
          this.advance()
        } else if (ec === 't') {
          value += '\t'
          this.advance()
        } else if (ec === 'r') {
          value += '\r'
          this.advance()
        } else if (ec === '\\') {
          value += '\\'
          this.advance()
        } else if (ec === '"') {
          value += '"'
          this.advance()
        } else if (ec === '0') {
          value += '\0'
          this.advance()
        } else if (ec === 'x') {
          this.advance() // 'x'
          let hex = ''
          for (let i = 0; i < 2; i++) {
            if (this.atEnd()) {
              this.error(start, 'unterminated string')
            }
            if (!isHexDigit(this.cur())) {
              this.error(backslashPos, 'invalid escape \\x')
            }
            hex += this.cur()
            this.advance()
          }
          value += String.fromCharCode(parseInt(hex, 16))
        } else if (ec === 'u') {
          this.advance() // 'u'
          if (this.atEnd()) {
            this.error(start, 'unterminated string')
          }
          if (this.cur() !== '{') {
            this.error(backslashPos, 'invalid escape \\u')
          }
          this.advance() // '{'
          let digits = ''
          for (;;) {
            if (this.atEnd()) {
              this.error(start, 'unterminated string')
            }
            if (isHexDigit(this.cur())) {
              digits += this.cur()
              this.advance()
              continue
            }
            break
          }
          if (digits.length === 0) {
            this.error(backslashPos, 'invalid escape \\u')
          }
          if (this.atEnd()) {
            this.error(start, 'unterminated string')
          }
          if (this.cur() !== '}') {
            this.error(backslashPos, 'invalid escape \\u')
          }
          this.advance() // '}'
          const cp = parseInt(digits, 16)
          if (cp > 0x10ffff) {
            this.error(backslashPos, 'invalid escape \\u')
          }
          value += String.fromCodePoint(cp)
        } else {
          this.error(backslashPos, 'invalid escape \\' + ec)
        }
        continue
      }
      // ordinary character
      const cp = this.input.codePointAt(this.pos)
      value += String.fromCodePoint(cp)
      this.advance()
    }
    return { kind: 'string', value, line: start.line, col: start.col }
  }

  scanRawString() {
    const start = this.here()
    this.advance() // 'r'
    this.advance() // opening quote
    let value = ''
    for (;;) {
      if (this.atEnd()) {
        this.error(start, 'unterminated string')
      }
      const c = this.cur()
      if (c === '"') {
        this.advance()
        break
      }
      const cp = this.input.codePointAt(this.pos)
      value += String.fromCodePoint(cp)
      this.advance()
    }
    return { kind: 'rawstring', value, line: start.line, col: start.col }
  }

  scanPunct() {
    const start = this.here()
    const two = this.cur() + this.peekAt(1)
    const twoCharOps = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
    if (twoCharOps.has(two)) {
      this.advance()
      this.advance()
      return { kind: 'punct', text: two, line: start.line, col: start.col }
    }
    const oneCharOps = new Set([
      '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.',
    ])
    const c = this.cur()
    if (oneCharOps.has(c)) {
      this.advance()
      return { kind: 'punct', text: c, line: start.line, col: start.col }
    }
    this.error(start, 'unexpected character ' + c)
  }

  next() {
    this.skipWhitespaceAndComments()
    if (this.atEnd()) return null
    const c = this.cur()
    if (c === 'r' && this.peekAt(1) === '"') {
      return this.scanRawString()
    }
    if (isIdentStart(c)) {
      return this.scanIdent()
    }
    if (isDigit(c)) {
      return this.scanNumber()
    }
    if (c === '"') {
      return this.scanString()
    }
    return this.scanPunct()
  }
}

function scan(input) {
  const scanner = new Scanner(input)
  const tokens = []
  for (;;) {
    const tok = scanner.next()
    if (tok === null) break
    tokens.push(tok)
  }
  return tokens
}

module.exports = { scan, ScanError }
"}

