        if (ec === 'n') {
          value += '\n'
          this.advance()
        } else if (ec === 't') {
          value += '\t'
          this.advance()
        } else if (ec === 'r') {
          value += '\r'
          this.advance()
        } else if (ec === '\\') {
          value += '\\'
          this.advance()
        } else if (ec === '"') {
          value += '"'
          this.advance()
        } else if (ec === '0') {
          value += '\0'
          this.advance()
        } else if (ec === 'x') {
          this.advance() // 'x'
