          this.advance() // 'u'
          if (this.atEnd()) {
            this.error(start, 'unterminated string')
          }
          if (this.cur() !== '{') {
            this.error(backslashPos, 'invalid escape \\u')
          }
          this.advance() // '{'
          let digits = ''
          for (;;) {
            if (this.atEnd()) {
              this.error(start, 'unterminated string')
            }
            if (isHexDigit(this.cur())) {
              digits += this.cur()
              this.advance()
              continue
            }
            break
          }
          if (digits.length === 0) {
            this.error(backslashPos, 'invalid escape \\u')
          }
          if (this.atEnd()) {
            this.error(start, 'unterminated string')
          }
          if (this.cur() !== '}') {
            this.error(backslashPos, 'invalid escape \\u')
          }
          this.advance() // '}'
          const cp = parseInt(digits, 16)
          if (cp > 0x10ffff) {
