import fs from 'node:fs'
import { scan, ScanError } from './scanner.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || (mode !== 'tokens' && mode !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const input = readStdin()

  let tokens
  try {
    tokens = scan(input)
  } catch (err) {
    if (err instanceof ScanError) {
      process.stderr.write(`error: ${err.line}:${err.col}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  let out = ''
  if (mode === 'tokens') {
    for (const tok of tokens) {
      const body =
        tok.kind === 'string' || tok.kind === 'rawstring' ? JSON.stringify(tok.value) : tok.text
      out += `${tok.line}:${tok.col} ${tok.kind} ${body}\n`
    }
  } else {
    const counts = { ident: 0, keyword: 0, number: 0, punct: 0, rawstring: 0, string: 0 }
    for (const tok of tokens) counts[tok.kind] += 1
    const order = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
    for (const kind of order) out += `${kind} ${counts[kind]}\n`
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
  process.exit(0)
}

